export type PublicIconFilename = (typeof PUBLIC_ICON_FILENAMES)[number]

/** Icons excluded from user-facing pickers (placeholders, duplicates). */
export const PUBLIC_ICON_PICKER_EXCLUDED: ReadonlySet<string> = new Set([
  'empty.svg',
])

export function getPublicIconPickerFilenames(): string[] {
  return PUBLIC_ICON_FILENAMES.filter(
    (filename) => !PUBLIC_ICON_PICKER_EXCLUDED.has(filename),
  )
}
